package com.example.data

object JamesData {
    val verses: List<Verse> = listOf(
        Verse(book = "Jak", chapter = 1, verseNumber = 1, text = "Mwen menm Jak, sèvitè Bondye ak Jezikri Seyè nou an, m'ap ekri lèt sa a pou douz branch fanmi yo ki gaye toupatou sou latè. Bonjou pou nou tout.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 2, text = "Frè m' yo, se pou nou santi nou kontan anpil lè nou wè nou tonbe anba nenpòt kalite eprèv.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 3, text = "Paske, nou konnen byen, lè konfyans nou gen nan Bondye a tonbe anba eprèv, sa ban nou pasyans.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 4, text = "Men, fòk pasyans sa a fin fè travay li nèt pou nou kapab bon nèt sou tout pwen, byen devlope, san nou pa manke anyen.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 5, text = "Si yon moun pami nou manke bon konprann, se pou l' mande Bondye, Bondye va ba li li. Paske, Bondye bay tout moun san mezire, pou gremesi.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 6, text = "Men, se pou li mande ak konfyans, san l' pa gen doutans. Paske, moun ki gen doutans, li tankou lanm lanmè van ap boulvèse.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 7, text = "Yon moun konsa pa bezwen mete nan tèt li l'ap resevwa anyen nan men Seyè a.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 8, text = "Se yon moun ki pa konnen sa li vle, ki toujou ap chanje lide nan tou sa l'ap fè.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 9, text = "Yon frè ki pòv dwe moutre jan li kontan lè Bondye fè kichòy pou li.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 10, text = "Konsa tou, yon frè ki rich dwe moutre jan l' kontan tou lè Bondye rabese li. Paske, moun ki rich gen pou pase tankou flè zèb.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 11, text = "Solèy la leve ak tout chalè li. Li cheche zèb la. Flè a tonbe. Tout bèlte l' disparèt. Konsa tou, moun rich la gen pou l' disparèt pandan tout kòmès li ap mache.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 12, text = "benediksyon pou moun ki sipòte eprèv li ak pasyans. Lè la fin pase anba eprèv yo, la resevwa pou rekonpans lavi Bondye te pwomèt tout moun ki renmen li yo.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 13, text = "Lè eprèv tonbe sou yon moun, lè l' anba tantasyon, moun sa a pa dwe di se Bondye k'ap tante li. Paske, menm jan Bondye pa janm anba tantasyon pou fè sa ki mal, konsa tou Bondye pa ka tante pesonn pou fè l' fè sa ki mal.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 14, text = "Men, lè yon moun anba tantasyon, se pwòp move dezi moun lan k'ap rale l', k'ap pouse li.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 15, text = "Konsa, move dezi a travay nan kè li, li fè l' fè peche. Lè peche a fin fèt, li bay lanmò.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 16, text = "Frè mwen renmen anpil yo, pa twonpe tèt nou sou bagay sa a.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 17, text = "Tout pi bèl favè, tout pi bon kado nou resevwa, se anwo nan syèl la yo soti, nan men Bondye ki kreye tout limyè. Bondye pa janm chanje, ni li pa gen anyen ki ta ka sanble yon chanjman nan li.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 18, text = "Gremesi pawòl verite a, li ban nou lavi jan l' te vle l' la, pou nou kapab gen premye plas nan tou sa li kreye.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 19, text = "Frè mwen renmen anpil yo, men yon bagay pou nou toujou chonje. Se pou tout moun prese louvri zòrèy yo pou yo ka tande. Men, pa kouri pale, pa prese fè kòlè.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 20, text = "Paske, kòlè lèzòm pa ka fè volonte Bondye.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 21, text = "Se poutèt sa, derasinen tout vye abitid ki pa dakò ak volonte Bondye ansanm ak tout kras mechanste ki nan lavi nou, voye yo jete. Soumèt nou devan Bondye, asepte pawòl li te plante nan kè nou an, paske se pawòl sa a ki ka sove nanm nou.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 22, text = "Se pou nou fè tou sa pawòl la mande nou fè. Pa rete ap koute ase. Lè sa a, se pwòp tèt nou n'ap twonpe.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 23, text = "Paske, lè yon moun tande pawòl la ase, san li pa fè sa pawòl la mande l' fè, li tankou yon moun ki gade figi l' nan yon glas.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 24, text = "Men, kou l' vire do l' ale, lamenm li bliye kisa li sanble.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 25, text = "Men, moun ki fikse je l' sou lalwa ki bon nèt la, lalwa ki bay libète a, si l' soti pou l' fè sa lalwa a mande, si li pa yon moun ki kite pawòl la antre nan yon zòrèy soti nan yon lòt, men ki fè sa lalwa a mande, moun sa a va jwenn benediksyon nan sa l'ap fè a.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 26, text = "Si yon moun kwè l'ap sèvi Bondye, pou anmenmtan li pa bride lang li, se tèt li l'ap twonpe. Sèvi Bondye jan sa a pa vo anyen.", bookId = 59),
        Verse(book = "Jak", chapter = 1, verseNumber = 27, text = "Men jan pou nou sèvi Bondye Papa a, si nou vle sèvi l' yon jan ki dakò ak volonte Bondye, yon jan ki bon tout bon devan li: SE pòte sekou bay timoun ki san papa. Se bay vèv yo lasistans lè yo nan lafliksyon. Se pa mele nan move bagay k'ap fèt sou latè pou nou pa pèdi kondisyon nou.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 1, text = "Frè m' yo, nou menm ki gen konfyans nan Jezikri, Seyè nou an ki gen tout pouvwa pou li, nou pa dwe gade sou figi moun.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 2, text = "Sipoze de moun vin antre nan asanble nou, yonn gen yon bèl rechanj sou li ak yon bag an lò nan dwèt li, lòt la tou pòv ak yon rad chire sou li.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 3, text = "Si nou leve pou n' salwe nonm ki gen bèl rechanj lan, epi nou di li: Msye, chita la nan bon plas sa a, epi si nou di pòv la: Ou menm, kanpe bò la a, osinon, chita atè bò pye m' lan,", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 4, text = "èske nou pa mete yon diferans nan mitan nou? Eske sa pa moutre nou gen move lide nan tèt nou lè n'ap jije moun?", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 5, text = "Frè mwen renmen anpil yo, tande sa byen: Bondye chwazi moun ki pòv sou latè pou yo ka rich nan konfyans nan Bondye, pou yo ka jwenn pòsyon pa yo nan peyi li te pwomèt moun ki renmen l' yo.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 6, text = "Men, nou menm, se meprize n'ap meprize moun pòv yo! Eske se pa moun rich yo k'ap kraze nou, k'ap trennen nou nan tribinal?", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 7, text = "Se yo menm tou k'ap pale bèl non Bondye ban nou an mal.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 8, text = "Jan sa ekri nan Liv la, lalwa gran Wa a di: Se pou ou renmen frè parèy ou tankou ou renmen pwòp tèt pa ou. Si nou fè sa, nou fè byen.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 9, text = "Men, si n'ap gade sou figi moun, nou fè peche. Lalwa ap kondannen nou pou dezobeyisans.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 10, text = "Paske, moun ki obsève tout lalwa a men ki dezobeyi yon sèl nan kòmandman yo, se tankou si l' te dezobeyi tout kòmandman yo.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 11, text = "Paske Bondye ki di: Pa fè adiltè, se li menm tou ki di: Pa touye moun. Konsa, menm si ou pa fè adiltè, men ou touye moun, ou dezobeyi lalwa a.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 12, text = "Se pou nou pale, se pou nou aji tankou moun ki gen pou pase anba jijman dapre lalwa ki ban nou libète a.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 13, text = "Paske, lè Bondye ap jije, l'ap san pitye pou moun ki te san pitye. Men, moun ki gen pitye pou lòt va soti tèt dwat lè jou jijman an.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 14, text = "Frè m' yo, kisa sa fè pou yon moun k'ap di li gen konfyans nan Bondye, si li pa fè bagay pou moutre li gen konfyans lan vre? Eske konfyans sa a ka delivre li?", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 15, text = "Sipoze gen yon frè osinon yon sè ki toutouni, ki pa manje kont li chak jou,", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 16, text = "si yonn nan nou di yo: Ou mèt ale. Chofe kò ou, manje plen vant ou, san li pa ba yo sa yo bezwen, kisa sa ap fè pou yo?", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 17, text = "Konsa tou pou konfyans nan Bondye a: si l' pa fè nou fè sa ki byen, si l' rete pou kont li, li mouri.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 18, text = "Men, gen moun ki va di: Ou menm, ou gen konfyans. Mwen menm, mwen fè sa ki byen. M'a reponn li: Moutre m' ki jan ou ka gen konfyans san ou pa fè sa ki byen, mwen menm m'ap moutre ou jan mwen gen konfyans ak sa m'ap fè ki byen.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 19, text = "Ou kwè gen yon sèl Bondye. Ou fè byen. Denmon yo tou yo kwè sa, men y'ap tranble sitèlman yo pè.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 20, text = "Gade jan ou manke konprann! Eske ou vle wè ki jan konfyans pa vo anyen si l' pa mache ak sa ou fè ki byen?", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 21, text = "Abraram granpapa nou, èske Bondye pa t' fè l' gras poutèt sa li te fè lè l' te ofri Izarak, pitit li a, sou lotèl la?", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 22, text = "Ou wè. Konfyans li te mache ansanm ak sa li te fè. Konsa tou, sa l' te fè a te fè konfyans li vin bon nèt.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 23, text = "Se konsa, pawòl ki te ekri nan Liv la rive vre: Abraram te mete konfyans li nan Bondye, epi Bondye fè l' gras. Se sak fè yo te rele Abraram zanmi Bondye.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 24, text = "Ou wè: se pa sèlman paske yon moun gen konfyans kifè Bondye fè l' gras, men se paske li fè sa ki byen anmenmtan an tou.", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 25, text = "Se menm jan an tou pou Rarab, fanm movèz vi a. Eske se pa t' poutèt sa l' te fè a Bondye te fè l' gras, lè l' te resevwa mesaje jwif yo, lè l' te fè yo pran yon lòt wout pou tounen lakay yo?", bookId = 59),
        Verse(book = "Jak", chapter = 2, verseNumber = 26, text = "Menm jan yon kò ki san nanm se yon kò ki mouri, konsa tou, konfyans nan Bondye ki pa mache ak fè sa ki byen se yon konfyans ki mouri.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 1, text = "Frè m' yo, se pa pou anpil moun nan mitan nou kouri dèyè plas dirèktè. Paske, konnen byen: lè nou dirèktè, Bondye ap jije nou pi sevè pase lòt yo.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 2, text = "Nou tout nou bite nan plizyè sans. Yon moun ki pa janm bite nan pawòl li, se yon moun ki bon nèt; moun sa a kapab kontwole tout kò l' byen tou.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 3, text = "Nou mete yon mò nan bouch chwal pou fè yo obeyi nou. Avèk sa, nou fè y ale kote nou vle.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 4, text = "Se menm jan an tou ak bato. Gwo kou l' gwo, gwo van te mèt ap pouse l', se yon ti gouvènay ki dirije li. Ak gouvènay tou piti sa a, kaptenn lan mennen l'l kote l' vle.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 5, text = "Konsa tou ak lang moun. Piti kou li piti, li vante tèt li pou gwo bagay li ka fè. Gade ki jan yon ti flanm dife ka boule yon gwo rakbwa!", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 6, text = "Enben, lang se tankou dife. Se la tout lenjistis rete. Paske se yon manm nan kò nou li ye, l'ap kontaminen tout kò a nèt. Se lanfè menm ki mete dife nan li. Apre sa, li menm pou tèt pa l', li mete dife nan tout lavi nou.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 7, text = "Moun ka donte tout kalite bèt, zwezo, bèt ki trennen sou vant, bèt ki nan lanmè. Li menm rive donte yo deja.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 8, text = "Men, pou lang lan menm, pesonn poko ka donte li. Se yon move bagay ou pa ka kontwole, li plen pwazon ki ka touye moun.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 9, text = "Avèk lang nou, nou fè lwanj Bondye papa nou. Avèk menm lang lan, nou bay moun madichon, moun Bondye te kreye pòtre ak li.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 10, text = "Menm bouch la bay benediksyon, li bay madichon tou. Frè m' yo, sa pa dwe fèt konsa.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 11, text = "Yon sous dlo pa ka bay dlo dous ak dlo sale anmenmtan.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 12, text = "Frè m' yo, yon pye fig frans pa ka donnen grenn oliv. Ni yon pye rezen pa ka donnen fig frans. Dlo sale pa ka bay dlo dous non plis.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 13, text = "Si gen nan mitan nou yon moun ki gen bon konprann, ki gen lespri, se pou l' moutre sa ak bon kondit li. Se pou l' fè sa ki byen san lògèy, men avèk bon konprann.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 14, text = "Men, si n'ap fè jalouzi nan kè nou, si nou kenbe moun nan kè nou, si n'ap kouri dèyè enterè pa nou, pa vante tèt nou, pa fè manti sou laverite a.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 15, text = "Bon konprann konsa pa soti nan Bondye, li soti nan lemonn, nan moun ak nan dyab la.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 16, text = "Paske, kote ki gen jalouzi, kote moun ap kouri dèyè enterè pa yo, fòk gen dezòd ak tout kalite mechanste.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 17, text = "Pou konmanse, moun ki gen bon konprann ki soti nan Bondye a ap fè volonte Bondye, l'ap viv byen ak tout moun, l'ap respekte tout moun, l'ap tande rezon, l'ap gen kè sansib, l'ap fè anpil anpil byen, li pa nan de fas ni nan ipokrit.", bookId = 59),
        Verse(book = "Jak", chapter = 3, verseNumber = 18, text = "Moun k'ap chache pou lèzòm viv byen yonn ak lòt, y'ap travay ak kè poze pou yo ka rekòlte yon lavi ki dwat devan Bondye.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 1, text = "Ki jan fè gen goumen ak kont nan mitan nou konsa? Kote sa soti? Sa soti nan move lanvi k'ap goumen nan kò nou.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 2, text = "Nou anvi yon bann bagay. Men, nou pa ka jwenn yo. Lè konsa, nou pare pou nou touye moun. Nou anvi sa ki pa pou nou. Men, nou pa ka jwenn yo. Lè konsa, se fè kont, se goumen. Si nou pa jwenn sa nou bezwen an, se paske nou pa mande Bondye.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 3, text = "Menm lè nou mande, nou pa resevwa anyen, paske nou mande mal. Nou mande bagay ki pou satisfè pwòp dezi pa nou sèlman.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 4, text = "Ala moun pa gen konfyans nan Bondye! Eske nou pa konnen lè nou zanmi lemonn, se lènmi Bondye nou ye! Moun ki vle zanmi lemonn, li vin lènmi Bondye.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 5, text = "Pa konprann se pou anyen yo ekri pawòl sa a nan Liv la: Bondye sitèlman renmen lespri li mete nan nou an, li fè jalouzi pou li.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 6, text = "Men, li fè nou yon pi gwo favè ankò, jan sa ekri nan Liv la: Bondye pran pozisyon kont moun ki gen lògèy yo. Men, moun ki soumèt devan l', li ba yo favè li.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 7, text = "Se poutèt sa, desann nou devan Bondye. Men, pran pozisyon kont Satan, la kouri kite nou.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 8, text = "Pwoche bò kot Bondye, Bondye va pwoche bò kote nou tou. Nou menm k'ap fè peche, lave men nou. Netwaye kè nou, nou menm k'ap woule de bò.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 9, text = "Se pou nou gen lapenn nan kè nou, kriye, plenn sò nou. Pase pou nou ri, pito nou kriye. Pase pou nou kontan, pito nou nan lapenn.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 10, text = "Desann nou devan Bondye, Bondye va leve nou.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 11, text = "Frè m' yo, piga nou yonn pale lòt mal. Moun ki pale yon frè mal, osinon ki jije frè li, se lalwa li pale mal, se lalwa li jije. Si w'ap jije lalwa, ou pa yon moun k'ap obsève lalwa, men ou pran pòz jij ou sou li.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 12, text = "Se Bondye ki fè lalwa. Se li menm tou ki sèl jij. Li gen pouvwa sove moun, li gen pouvwa kite yo pèdi. Men, ou menm k'ap jije frè parèy ou, ki moun ou konprann ou ye?", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 13, text = "Koulye a, se ak nou m'ap pale, nou menm k'ap di: jòdi a osinon denmen, n'a pral nan tèl lavil. Rive la, n'a pase yon lanne, n'a fè kòmès ak anpil benefis.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 14, text = "Nou pa menm konnen sa lavi nou va ye denmen. Lavi nou tankou yon nwaj. Li parèt pou yon ti tan. Apre sa, li disparèt.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 15, text = "Okontrè, men sa pou nou te di: Si Bondye vle, n'a wè denmen, n'a fè sa osinon sa.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 16, text = "Men, koulye a nan grandizè nou, se vante n'ap vante tèt nou. Se yon move bagay pou moun vante tèt yo konsa.", bookId = 59),
        Verse(book = "Jak", chapter = 4, verseNumber = 17, text = "Se poutèt sa, moun ki pa fè byen li konnen li gen pou l' fè a, li fè peche.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 1, text = "Koulye a, nou menm moun rich yo, se pou nou m'ap pale: Nou mèt konmanse kriye, konmanse pouse rèl pou malè ki pral tonbe sou nou yo.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 2, text = "Richès nou yo fin pouri. Vèmin fin manje rad nou yo.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 3, text = "Lò nou ak lajan nou yo fin wouye. Lawouj la pral kanpe pou kondannen nou, li va devore vyann nou tankou dife. Nou te ranmase kont lajan nou nan dènye tan sa a.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 4, text = "Gade! Nou pa t' peye lajan nou te dwe peye travayè yo ki t'ap travay pou nou nan jaden. Tande jan y'ap rele! Travayè ki te ranmase rekòt pou nou yo ap plede rele! Rèl yo rive jouk nan zòrèy Bondye, Mèt ki gen tout pouvwa a.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 5, text = "Nou viv sou latè nan plezi ak nan jwisans. Nou manje jouk nou gra tankou bèt ki pare pou labatwa.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 6, text = "Nou kondannen moun ki inonsan, nou fè touye yo. Yo menm, yo pa fè fòs ak nou.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 7, text = "Se poutèt sa, frè m' yo, annou pran pasyans jouk jou Seyè a va vini. Gade jan kiltivatè a gen pasyans. Li gen pou l' rete tann anvan pou tè a ba li yon bèl rekòt. Li pran pasyans, li rete tann lapli premye sezon an jouk lapli dènye sezon an.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 8, text = "Nou menm tou, pran pasyans. Bay kè nou kouraj, paske Mèt la pa lontan vini.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 9, text = "Frè m' yo, pa plenyen yonn sou do lòt pou nou pa tonbe anba jijman Bondye. Men jij la la nan papòt la.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 10, text = "Frè m' yo, chonje pwofèt yo ki te pale nan non Mèt la. Pran egzanp sou yo, pou jan yo te gen pasyans lè yo t'ap soufri.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 11, text = "Paske yo te soufri ak pasyans, nou di yo se moun Bondye beni. Nou tande ki jan Jòb te gen pasyans, nou wè bout pou bout sa Bondye te fè pou li, paske Bondye gen bon kè, li gen kè sansib.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 12, text = "Anvan tout lòt bagay, frè m' yo, men sa ki pi enpòtan: piga nou fè sèman sou syèl la, ni sou latè a, ni sou ankenn lòt bagay. Lè nou di wi, se wi, non, se non. Konsa, nou p'ap tonbe anba jijman Bondye.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 13, text = "Si yon moun nan nou ap soufri, se pou li lapriyè. Si yon moun nan nou gen kè kontan, se pou l' chante kantik.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 14, text = "Si yon moun nan nou malad, se pou l' rele chèf reskonsab yo nan legliz la. Y'a lapriyè pou li, y'a pase lwil sou li nan non Seyè a.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 15, text = "Lè lapriyè a fèt ak konfyans, li va delivre malad la. Seyè a va fè l' leve gaya. Si li te fè kèk peche, Bondye va padonnen li.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 16, text = "Se pou nou konfese peche nou yo yonn bay lòt. Se pou yonn lapriyè pou lòt, pou nou kapab geri. Lè yon moun ap viv dwat devan Bondye, lapriyè moun sa a gen anpil pouvwa.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 17, text = "Pwofèt Eli te yon moun menm jan ak nou. Li te lapriyè rèd pou lapli pa t' tonbe. Konsa vre, lapli pa tonbe pandan twazan sis mwa.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 18, text = "Apre sa, li lapriyè ankò. Lè sa a, syèl la louvri, lapli tonbe, latè bay bèl rekòt.", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 19, text = "Frè m' yo, si yonn nan nou pèdi chemen laverite a, epi yon lòt frè mennen l' tounen ankò,", bookId = 59),
        Verse(book = "Jak", chapter = 5, verseNumber = 20, text = "konnen sa byen: lè yon moun pèdi chemen l' poutèt peche li yo, si yon lòt mennen l' tounen, se yon nanm li rache anba lanmò. Anmenmtan, li jwenn padon pou anpil peche.", bookId = 59)
    )
}
